ALTER TABLE qr_tables ADD COLUMN id uuid NOT NULL DEFAULT gen_random_uuid();
ALTER TABLE qr_tables ADD CONSTRAINT qr_tables_id UNIQUE(id);
ALTER TABLE qr_tables ADD COLUMN seats integer NOT NULL DEFAULT 4 CHECK(seats BETWEEN 1 AND 20);
ALTER TABLE qr_tables ADD COLUMN x integer NOT NULL DEFAULT 15 CHECK(x BETWEEN 0 AND 85);
ALTER TABLE qr_tables ADD COLUMN y integer NOT NULL DEFAULT 15 CHECK(y BETWEEN 0 AND 80);
ALTER TABLE qr_tables ADD COLUMN zone text NOT NULL DEFAULT 'Зал';
ALTER TABLE qr_tables ADD COLUMN shape text NOT NULL DEFAULT 'round' CHECK(shape IN ('round','square'));
WITH positions AS (SELECT token,row_number() OVER(ORDER BY name)-1 AS n FROM qr_tables)
UPDATE qr_tables t SET x=10+(p.n%3)*30,y=15+((p.n/3)%3)*25 FROM positions p WHERE p.token=t.token;
CREATE TABLE v2_settings(id integer PRIMARY KEY CHECK(id=1),data jsonb NOT NULL);
INSERT INTO v2_settings VALUES(1,'{"floorPlanVerified":false,"referralPoints":100,"referralsEnabled":true,"giftValidityDays":365}');
ALTER TABLE reservations ADD COLUMN table_id uuid REFERENCES qr_tables(id);
CREATE INDEX reservations_table ON reservations(table_id,date,status);
CREATE TABLE dine_visits(id uuid PRIMARY KEY,table_id uuid NOT NULL REFERENCES qr_tables(id),reservation_id uuid UNIQUE REFERENCES reservations(id),join_code text NOT NULL,status text NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','CLOSED')),created_at timestamptz NOT NULL DEFAULT now(),closed_at timestamptz);
CREATE UNIQUE INDEX one_open_visit ON dine_visits(table_id) WHERE status='OPEN';
CREATE TABLE dine_members(visit_id uuid NOT NULL REFERENCES dine_visits(id),owner text NOT NULL,user_id uuid REFERENCES users(id),PRIMARY KEY(visit_id,owner));
ALTER TABLE orders ADD COLUMN visit_id uuid REFERENCES dine_visits(id);
ALTER TABLE orders ADD COLUMN gift_paid integer NOT NULL DEFAULT 0 CHECK(gift_paid>=0);
CREATE INDEX orders_visit ON orders(visit_id);
CREATE TABLE waiter_calls(id uuid PRIMARY KEY,visit_id uuid NOT NULL REFERENCES dine_visits(id),kind text NOT NULL CHECK(kind IN ('WAITER','BILL')),status text NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','DONE')),created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX waiter_call_open ON waiter_calls(visit_id,kind) WHERE status='OPEN';
CREATE TABLE bill_shares(id uuid PRIMARY KEY,visit_id uuid NOT NULL REFERENCES dine_visits(id),position integer NOT NULL,amount integer NOT NULL CHECK(amount>0),paid boolean NOT NULL DEFAULT false,paid_at timestamptz,UNIQUE(visit_id,position));
CREATE TABLE customer_preferences(user_id uuid PRIMARY KEY REFERENCES users(id),favorites jsonb NOT NULL DEFAULT '[]',max_spice integer NOT NULL DEFAULT 3 CHECK(max_spice BETWEEN 0 AND 3),avoid_allergens jsonb NOT NULL DEFAULT '[]');
CREATE TABLE restaurant_events(id uuid PRIMARY KEY,title text NOT NULL,description text NOT NULL,starts_at timestamptz NOT NULL,capacity integer NOT NULL CHECK(capacity BETWEEN 1 AND 300),active boolean NOT NULL DEFAULT false);
CREATE TABLE event_signups(event_id uuid NOT NULL REFERENCES restaurant_events(id),user_id uuid NOT NULL REFERENCES users(id),guests integer NOT NULL CHECK(guests BETWEEN 1 AND 10),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(event_id,user_id));
CREATE TABLE gift_certificates(id uuid PRIMARY KEY,buyer_id uuid NOT NULL REFERENCES users(id),code text UNIQUE NOT NULL,amount integer NOT NULL CHECK(amount>=10000),balance integer NOT NULL DEFAULT 0 CHECK(balance>=0),status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','ACTIVE','CANCELLED')),message text NOT NULL DEFAULT '',idempotency_key uuid NOT NULL,expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(buyer_id,idempotency_key));
CREATE TABLE gift_redemptions(id uuid PRIMARY KEY,certificate_id uuid NOT NULL REFERENCES gift_certificates(id),order_id uuid NOT NULL REFERENCES orders(id),amount integer NOT NULL CHECK(amount>0),actor_id uuid NOT NULL REFERENCES users(id),idempotency_key uuid NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE referral_codes(user_id uuid PRIMARY KEY REFERENCES users(id),code text UNIQUE NOT NULL);
CREATE TABLE referrals(invitee_id uuid PRIMARY KEY REFERENCES users(id),inviter_id uuid NOT NULL REFERENCES users(id),rewarded_order_id uuid UNIQUE REFERENCES orders(id),reward_points integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),CHECK(invitee_id<>inviter_id));
